import java.util.Scanner;

public static void main(String[] args) throws Exception {
    Scanner sc = new Scanner(System.in);
    int sumA = 0;
    int sumB = 0;

    for(int i = 0; i < 9; i++){
        int n = sc.nextInt();
        sumA += n;
    }

    for(int j = 0; j < 8; j++){
        int m = sc.nextInt();
        sumB += m;
    }

    System.out.println(Math.max(0, sumA - sumB + 1));
}
